33	    <span id="email-hint" class="hint">Format: you@example.com</span>
34	    <!-- DO: Use standard HTML validation attributes like type="email" and required -->
35	    <!-- Set data-error to the error message's id. The aria-invalid script lists that id in aria-describedby while the field is invalid. -->
36	    <input
