607	   rule working where :user-invalid isn't supported: in a plain selector list, one
608	   unsupported selector drops the whole rule. */
609	:is(:user-invalid, .user-invalid-fallback) {
610	  border-color: #d93025;
611	  background-color: #fce8e6;
612	}
