615	  display: block;
616	}
617	```
618	
619	### JavaScript Fallback
620	
621	Use a reusable utility that tracks interaction state using a `WeakMap`. This avoids polluting the DOM with "dirty" classes or data attributes.
622	
623	```javascript
624	const UserInvalidFallback = (() => {
625	  const dirtyState = new WeakMap();
626	
627	  const updateState = (input) => {
628	    // validity.valid gives the current state without firing an 'invalid' event, as checkValidity() does.
629	    const isValid = input.validity.valid;
630	
631	    // Update both visual and ARIA state
632	    input.classList.toggle('user-invalid-fallback', !isValid);
633	    input.classList.toggle('user-valid-fallback', isValid);
634	
635	    input.setAttribute('aria-invalid', isValid ? 'false' : 'true');
636	    linkError(input, !isValid);
637	  };
638	
639	  // List the error message (the id in data-error) in aria-describedby only while it's
640	  // shown: text that aria-describedby references is announced even when it's hidden.
641	  const linkError = (input, shown) => {
642	    const errorId = input.dataset.error;
643	    if (!errorId) return;
644	    const ids = (input.getAttribute('aria-describedby') || '').split(/\s+/).filter((id) => id && id !== errorId);
645	    if (shown) ids.push(errorId);
646	    if (ids.length) input.setAttribute('aria-describedby', ids.join(' '));
647	    else input.removeAttribute('aria-describedby');
648	  };
649	
650	  const handleEvent = (event) => {
651	    const input = event.target;
652	
653	    if (event.type === 'reset') {
654	      const controls = input.elements || [];
655	      for (const control of controls) {
656	        dirtyState.delete(control);
657	        control.classList.remove('user-invalid-fallback');
658	        control.classList.remove('user-valid-fallback');
659	        if (control.matches('input, select, textarea')) control.setAttribute('aria-invalid', 'false');
660	        if (control.dataset?.error) linkError(control, false);
661	      }
662	      return;
663	    }
664	
665	    if (!input.checkValidity) return;
666	
667	    // A submit attempt counts as interaction: the browser fires 'invalid' on each failing
668	    // field, including required fields the user never touched, so flag them all.
669	    if (event.type === 'invalid') {
670	      dirtyState.set(input, { hasInteracted: true, hasBlurred: true });
671	      updateState(input);
672	      return;
673	    }
674	
675	    if (event.type === 'input' || event.type === 'change') {
676	      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
677	      state.hasInteracted = true;
678	      dirtyState.set(input, state);
679	      if (state.hasBlurred) {
680	        updateState(input);
681	      }
682	    } else if (event.type === 'blur') {
683	      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
684	      state.hasBlurred = true;
685	      dirtyState.set(input, state);
686	      if (state.hasInteracted) {
687	        updateState(input);
688	      }
689	    }
690	  };
691	
692	  const init = (root = document) => {
693	    if (CSS.supports('selector(:user-invalid)')) return;
694	
695	    // Firefox and Safari expose an empty required field as invalid from page load.
696	    root.querySelectorAll('input, select, textarea').forEach((el) => {
697	      if (!el.hasAttribute('aria-invalid')) el.setAttribute('aria-invalid', 'false');
698	    });
699	
700	    root.addEventListener('blur', handleEvent, true); // Capture phase
701	    root.addEventListener('input', handleEvent);
702	    root.addEventListener('change', handleEvent);
703	    root.addEventListener('invalid', handleEvent, true); // invalid doesn't bubble
704	    root.addEventListener('reset', handleEvent, true); // Capture resets
705	  };
706	
707	  return { init };
708	})();
709	
710	// Initialize for a specific form
711	const form = document.querySelector('#demo-form');
712	UserInvalidFallback.init(form);
713	```
